double findHigh(int bars)
{
    double maxH = 0;
    for (int i = 0; i < bars; i++)
    {
        double h = iHigh(_Symbol, PERIOD_CURRENT, i);
        if (h > maxH) maxH = h;
    }
    return maxH;
}

double findLow(int bars)
{
    double minL = DBL_MAX;
    for (int i = 0; i < bars; i++)
    {
        double l = iLow(_Symbol, PERIOD_CURRENT, i);
        if (l < minL) minL = l;
    }
    return minL;
}

// --------------------------------------------------------------------
// Initialization
// --------------------------------------------------------------------
int OnInit()
{
    // Configure buffers
    SetIndexBuffer(0, BuyEntryBuffer);
    SetIndexBuffer(1, SellEntryBuffer);
    SetIndexBuffer(2, TakeProfitBuffer);
    SetIndexBuffer(3, StopLossBuffer);

    // Plot arrow positions
    PlotIndexSetInteger(0, PLOT_ARROW, 233); // Buy entry arrow up
    PlotIndexSetInteger(1, PLOT_ARROW, 234); // Sell entry arrow down
    PlotIndexSetInteger(2, PLOT_ARROW, 240); // Take profit arrow up
    PlotIndexSetInteger(3, PLOT_ARROW, 241); // Stop loss arrow down

    // Short name of the indicator
    IndicatorShortName("Signal Indicator");

    return (INIT_SUCCEEDED);
}

// --------------------------------------------------------------------
// Calculation (called every tick / every bar)
// --------------------------------------------------------------------
int OnCalculate(const int rates_total,
                const int prev_calculated,
                const datetime &time[], const double &open[],
                const double &high[], const double &low[],
                const double &close[],
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
{
    for (int i = 0; i < rates_total; i++)
    {
        double curHigh = iHigh(_Symbol, PERIOD_CURRENT, i);
        double curLow  = iLow(_Symbol, PERIOD_CURRENT, i);

        double recentHigh = findHigh(BarsN);
        double recentLow  = findLow(BarsN);

        if (curHigh > recentHigh)
        {
            BuyEntryBuffer[i] = curHigh;
            TakeProfitBuffer[i] = curHigh + Tppoints * _Point;
            StopLossBuffer[i]  = curHigh - Slpoints * _Point;
        }
        else if (curLow  < recentLow)
        {
            SellEntryBuffer[i] = curLow;
            TakeProfitBuffer[i] = curLow - Tppoints * _Point;
            StopLossBuffer[i]  = curLow + Slpoints * _Point;
        }
    }
    return (rates_total);
}

