// --------------------------------------------------------------------
double findLow(int bars)
{
    double minL = DBL_MAX;
    for (int i = 0; i < bars; i++)
    {
        double l = iLow(_Symbol, PERIOD_CURRENT, i);
        if (l < minL) minL = l;
    }
    return minL;
}
